const AMBER = ORANGE, RED = "#C23B22", BLUE = "#3D4E96", GREEN = "#3F7D5C", OLIVE = DARKGREY;
const STAGE_COLORS = { Received: BLUE, Manufacturing: ORANGE, Packing: OLIVE, Shipped: GREEN };
// Which physical carton an order's products get packed into — set once
