function HazardStripe({ height = 4 }) {
  return (
    <div style={{ height: 7, background: NAVY, position: "relative", overflow: "hidden" }}>
      <div style={{
        position: "absolute", top: 0, left: 0, height: "100%", width: 64,
        background: ORANGE,
        clipPath: "polygon(0 0, 75% 0, 45% 100%, 0 100%)",
      }} />
    </div>
  );
}
function AccentUnderline() {
  return <div style={{ width: 44, height: 7, background: ORANGE, clipPath: "polygon(0 0, 85% 0, 100% 100%, 15% 100%)" }} />;
}
