function uid(prefix) { return prefix + "-" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6); }
// uid() embeds a base36 timestamp right after "prefix-", followed by a fixed
// 4-character random suffix. Decoding it lets us recover true chronological
// order for rows pulled from more than one array (e.g. Extrusion 1 + 2
// combined) without adding a separate createdAt field to the data model.
function timestampFromUid(id) {
  if (!id || typeof id !== "string") return 0;
  const dash = id.indexOf("-");
  if (dash === -1) return 0;
  const rest = id.slice(dash + 1);
  const tsPart = rest.slice(0, rest.length - 4);
  const n = parseInt(tsPart, 36);
  return Number.isFinite(n) ? n : 0;
}
function fmtMoney(n) { return "£" + (Number(n) || 0).toFixed(2); }
// `.toISOString()` always converts to UTC before formatting — during
// British Summer Time (UTC+1), local midnight is 23:00 the PREVIOUS day in
// UTC, so slicing the date out of it silently returns yesterday's date for
// roughly the first hour of every day, or — worse, if midnight was set
// deliberately first — returns yesterday's date all day, every day, all
// summer. Every "today" computation must use local getters (getFullYear/
// getMonth/getDate), never toISOString, or dates quietly drift by a day.
/* A Date as YYYY-MM-DD in LOCAL time.
   Never `toISOString().slice(0, 10)` for this: that is UTC, and from late
   March to late October the Isle of Man is an hour ahead of it, so local
   midnight formats as the PREVIOUS day. The make list shipped with exactly
   that in `.32` — every date a day early all summer — and the sandbox tests
   couldn't see it because the sandbox runs in UTC. `static_audit.js` did. */
function localISO(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function todayISO() { return localISO(new Date()); }
function daysAgoLocal(n) {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

